  }

  @Patch('combos/:id')
  editarCombo(@Param('id', ParseIntPipe) id: number, @Req() req: any, @Body() body: any) {
    return this.service.editarCombo(id, req.restaurantId, body);
  }

  @Delete('combos/:id')
  deletarCombo(@Param('id', ParseIntPipe) id: number, @Req() req: any) {
